import base64
import hashlib
import hmac
from urllib.parse import parse_qs, urlencode, urlsplit

_ALLOWED = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")


def _b64url(data):
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def make_verifier(random_bytes):
    if not 32 <= len(random_bytes) <= 96:
        raise ValueError("a verifier needs 32 to 96 random bytes")
    return _b64url(random_bytes)


def challenge_for(verifier):
    if not 43 <= len(verifier) <= 128 or not set(verifier) <= _ALLOWED:
        raise ValueError("not a valid code verifier")
    return _b64url(hashlib.sha256(verifier.encode("ascii")).digest())


def authorization_url(endpoint, client_id, redirect_uri, scopes, state, challenge):
    query = urlencode([
        ("response_type", "code"),
        ("client_id", client_id),
        ("redirect_uri", redirect_uri),
        ("scope", " ".join(scopes)),
        ("state", state),
        ("code_challenge", challenge),
        ("code_challenge_method", "S256"),
    ])
    return endpoint + "?" + query


def read_callback(url, expected_state):
    params = parse_qs(urlsplit(url).query)
    state = params.get("state", [""])[0]
    if not state or not hmac.compare_digest(state, expected_state):
        raise ValueError("state mismatch")
    if "error" in params:
        raise PermissionError(f"authorization failed: {params['error'][0]}")
    code = params.get("code", [""])[0]
    if not code:
        raise ValueError("no code")
    return code

