RFC_BYTES = bytes([116, 24, 223, 180, 151, 153, 224, 37, 79, 250, 96, 125, 216, 173, 187, 186,
                   22, 212, 37, 77, 105, 214, 191, 240, 91, 88, 5, 88, 83, 132, 141, 121])

@test("the RFC 7636 example")
def _():
    v = make_verifier(RFC_BYTES)
    check_eq(v, "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk")
    check_eq(challenge_for(v), "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM")

@test("verifier lengths")
def _():
    check_eq(len(make_verifier(bytes(32))), 43)
    check_eq(len(make_verifier(bytes(96))), 128)
    check_raises(ValueError, make_verifier, bytes(31))
    check_raises(ValueError, make_verifier, bytes(97))
    check("=" not in make_verifier(bytes(range(40))))

@test("checking verifiers")
def _():
    check_raises(ValueError, challenge_for, "a" * 42)
    check_raises(ValueError, challenge_for, "a" * 129)
    check_raises(ValueError, challenge_for, "a" * 42 + "+")
    check_raises(ValueError, challenge_for, "a" * 42 + "=")
    check_eq(len(challenge_for("a" * 43 + "-._~")), 43)

@test("the authorization URL")
def _():
    url = authorization_url("https://auth.example.com/authorize", "my app", "http://127.0.0.1:8765/callback",
                            ["calendar.read", "offline_access"], "st4te", "E9Mel")
    check_eq(url, "https://auth.example.com/authorize?response_type=code&client_id=my+app"
                  "&redirect_uri=http%3A%2F%2F127.0.0.1%3A8765%2Fcallback&scope=calendar.read+offline_access"
                  "&state=st4te&code_challenge=E9Mel&code_challenge_method=S256")

@test("reading the callback")
def _():
    check_eq(read_callback("http://127.0.0.1:8765/callback?code=abc123&state=s1", "s1"), "abc123")
    check_raises(ValueError, read_callback, "http://127.0.0.1:8765/callback?code=abc123&state=evil", "s1")
    check_raises(ValueError, read_callback, "http://127.0.0.1:8765/callback?code=abc123", "s1")
    check_raises(ValueError, read_callback, "http://127.0.0.1:8765/callback?state=s1", "s1")
    check_raises(ValueError, read_callback, "http://127.0.0.1:8765/callback?state=s1&code=", "s1")

@test("errors from the service")
def _():
    try:
        read_callback("http://127.0.0.1/cb?error=access_denied&state=s1", "s1")
        check(False, "expected PermissionError")
    except PermissionError as e:
        check("access_denied" in str(e))
    check_raises(ValueError, read_callback, "http://127.0.0.1/cb?error=access_denied&state=other", "s1")

